(5089670, 742590, 31535, '<td valign="top">Dressing and stuffing are my favorite part of the holiday meals. I''m sure your dish tastes great.</td>', 'Dressing and stuffing are my favorite part of the holiday meals. I''m sure your dish tastes great.', '2008-11-29 01:49:48.000000', NULL, 1),
(5089674, 742542, 31535, '<td valign="top">Simple and efective. I like the muted colour of fall.</td>', 'Simple and efective. I like the muted colour of fall.', '2008-11-29 01:51:27.000000', NULL, 1),
(5089679, 742801, 31535, '<td valign="top">This is a well dressed plate. Nicely thought out although the multi-colored background is a little distracting. A more neutral background would bring more focus to the food.</td>', 'This is a well dressed plate. Nicely thought out although the multi-colored background is a little distracting. A more neutral background would bring more focus to the food.', '2008-11-29 01:53:58.000000', NULL, 1),
(5089684, 742724, 31535, '<td valign="top">I think if you shot from a higher angle, you could cut out the tinfoil in the background and bring more focus to the turkey meat.</td>', 'I think if you shot from a higher angle, you could cut out the tinfoil in the background and bring more focus to the turkey meat.', '2008-11-29 01:58:18.000000', NULL, 1),
(5089688, 742829, 31535, '<td valign="top">Sorry, but it''s not the most interesting perspective you could have taken here. I know you tried to get it all in the frame, but you also got the computer and the furnace in there.</td>', 'Sorry, but it''s not the most interesting perspective you could have taken here. I know you tried to get it all in the frame, but you also got the computer and the furnace in there.', '2008-11-29 02:01:27.000000', NULL, 1),
(5089697, 742653, 31535, '<td valign="top">I''m sure this dish is very tasty, but the way you shot it here does not show that. Direct flash is never good.</td>', 'I''m sure this dish is very tasty, but the way you shot it here does not show that. Direct flash is never good.', '2008-11-29 02:05:12.000000', NULL, 1),
(5089700, 742582, 31535, '<td valign="top">Nicely exposed and I like the angle you''ve taken. The out of focus food in foreground and the crisp focus on the lady are in perfect balance. 7</td>', 'Nicely exposed and I like the angle you''ve taken. The out of focus food in foreground and the crisp focus on the lady are in perfect balance. 7', '2008-11-29 02:06:26.000000', NULL, 1),
