INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5119182, 742750, 108248, '<td valign="top">Lydia, I totally see what you were trying to accomplish in this photo and am sorry it got dq''ed. To me the focus is the toast and you are just using the other picture as a sort of backdrop, but apparently others see it differently. Don''t let it get you down!!!</td>', 'Lydia, I totally see what you were trying to accomplish in this photo and am sorry it got dq''ed. To me the focus is the toast and you are just using the other picture as a sort of backdrop, but apparently others see it differently. Don''t let it get you down!!!', '2008-12-09 10:31:38.000000', NULL, 0),
(5119189, 742750, 89723, '<td valign="top">Lydia,<br/> <br/> I disagree with the SC decision. It''s very unforunate!</td>', 'Lydia,  I disagree with the SC decision. It''s very unforunate!', '2008-12-09 10:34:01.000000', NULL, 0),
(5119200, 742750, 63398, '<td valign="top">I still like it; that it''s a picture of a pictuere doesn''t bother me in the slightest.......it''s still a delightful and warm composition.</td>', 'I still like it; that it''s a picture of a pictuere doesn''t bother me in the slightest.......it''s still a delightful and warm composition.', '2008-12-09 10:43:16.000000', NULL, 0),
(5119324, 742750, 53781, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by LydiaToo:</b></div><hr/><i> I forgot to shoot for the speed challenge until the "Feast" was over and all of the guests were long gone... so I put a photo I HAD taken (earlier that day, during the challenge period) up on my monitor, set a glass of wine in front of it... and then drank the wine while I processed the new photo.  </i></td></tr></table> <br/> <br/>I don''t understand the ruling on the DQ. You took the background photo during the time of the challenge, it''s not someone elses work, you were present there when that photo was taken, so to me you were not trying to fool me.</td>', 'Originally posted by LydiaToo: I forgot to shoot for the speed challenge until the "Feast" was over and all of the guests were long gone... so I put a photo I HAD taken (earlier that day, during the challenge period) up on my monitor, set a glass of wine in front of it... and then drank the wine while I processed the new photo.    I don''t understand the ruling on the DQ. You took the background photo during the time of the challenge, it''s not someone elses work, you were present there when that photo was taken, so to me you were not trying to fool me.', '2008-12-09 11:45:18.000000', NULL, 0),
(5119344, 742750, 51793, '<td valign="top">Ughhh that sucks. I just found out I''m sorry.</td>', 'Ughhh that sucks. I just found out I''m sorry.', '2008-12-09 11:54:56.000000', NULL, 0),
(5119430, 742750, 52549, '<td valign="top">Lydia, I''m really sorry this has happened to you ;-((</td>', 'Lydia, I''m really sorry this has happened to you ;-((', '2008-12-09 12:34:53.000000', NULL, 0),
